def seed_hq_facilities(apps, schema_editor):
    Branch = apps.get_model("people", "Branch")
    EquipmentType = apps.get_model("events", "EquipmentType")
    Vehicle = apps.get_model("events", "Vehicle")
    hq = Branch.objects.filter(is_headquarters=True, is_active=True).first()
    if hq is None:
        hq = Branch.objects.filter(is_active=True).order_by("id").first()
    if hq is None:
        return
    for sort_order, name, qty in (
        (10, "Electric fan", 3),
        (20, "Projector", 1),
    ):
        EquipmentType.objects.get_or_create(
            branch=hq,
            name=name,
            defaults={
                "quantity_available": qty,
                "is_active": True,
                "sort_order": sort_order,
            },
        )
    Vehicle.objects.get_or_create(
        branch=hq,
        name="Isuzu Travis",
        defaults={"is_active": True, "sort_order": 10},
    )


